{"packet_id": "D006-01", "doc_id": "D006", "jurisdiction": "Berkeley, CA", "category": "rent_increase_limits", "lifecycle": "enacted", "title": "Measure BB 5% cap on Annual General Adjustments", "requirement": "The Rent Board may not approve an Annual General Adjustment above 5% in a year, even where the Rent Ordinance CPI formula would produce a larger increase.", "key_value": "max 5% per year", "coverage_conditions": "Landlords of fully covered rental units in Berkeley, whose yearly increase is the AGA set by the elected Rent Board.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": "The cap does not stop a landlord from using banked, unused AGAs from earlier years to raise rent up to the rent ceiling.", "penalty": null, "effective_date": null, "citation": "Berkeley Rent Ordinance, Measure BB: Annual General Adjustment cap", "quoted_span": "The maximum AGA is 5%. This means that, if the formula in the Rent Ordinance results in an AGA that is greater than 5%, the AGA approved by the Board for that year can be no more than 5%.", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D006-01", "doc_id": "D006", "jurisdiction": "Berkeley, CA", "category": "rent_increase_limits", "lifecycle": "enacted", "title": "Measure BB coverage of shared-facility and government-subsidized units", "requirement": "Units sharing a kitchen or bath with the landlord are exempt only if the landlord lived on the property at the tenancy start; government-owned or subsidized units must be registered as fully or partially covered.", "key_value": null, "coverage_conditions": "Berkeley rental units: shared kitchen or bath units, and government-owned or subsidized units including Section 8, Shelter Plus Care, VASH, LIHTC and similar subsidies.", "applicability": {"built_on_or_before": "1980", "built_after": null, "date_basis": "certificate_of_occupancy", "min_units": null, "max_units": null, "owner_dependent": true, "other": null}, "exemptions": "Partially covered: new construction with a certificate of occupancy after 1980, most single-family homes and condominiums, and certain HUD-insured or federally exempt subsidized units.", "penalty": null, "effective_date": null, "citation": "Berkeley Rent Ordinance, Measure BB: coverage of shared-facility and subsidized units", "quoted_span": "Where the tenant shares a kitchen or bath facilities with the landlord, the unit will be exempt from the Rent Ordinance only if the landlord lived in a unit on the same property at the start of the tenancy.", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D006-01", "doc_id": "D006", "jurisdiction": "Berkeley, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Measure BB nonpayment eviction threshold", "requirement": "A landlord may not evict for nonpayment of rent unless the tenant owes rental debt at least equal to one month of Fair Market Rent for an equivalent unit.", "key_value": "1 month Fair Market Rent", "coverage_conditions": "Tenants in Berkeley units fully or partially covered by the Rent Ordinance.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Berkeley Rent Ordinance, Measure BB: just cause, nonpayment of rent", "quoted_span": "For a landlord to evict a tenant for nonpayment of rent, the tenant must owe an amount of rental debt equal to or greater than one month of the Fair Market Rent (FMR) value for a unit of equivalent size in the metro area Oakland-Fremont, CA HUD Metro FMR as determined by the US Department of Housing and Urban Development for the fiscal year in which the rent is demanded.", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D006-01", "doc_id": "D006", "jurisdiction": "Berkeley, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Measure BB bar on eviction for refusing a new lease", "requirement": "A landlord cannot evict a tenant for failing to sign a substantially similar lease when a fixed-term lease expires.", "key_value": null, "coverage_conditions": "Tenants in Berkeley units fully or partially covered by the Rent Ordinance.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Berkeley Rent Ordinance, Measure BB: just cause, failure to sign new lease", "quoted_span": "A landlord cannot evict a tenant for failing to sign a substantially similar lease upon expiration of a fixed-term lease.", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D006-01", "doc_id": "D006", "jurisdiction": "Berkeley, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Measure BB limits on lease-breach evictions", "requirement": "To evict for a lease breach the landlord must show the conduct was unreasonable and caused substantial actual damage, and the notice to stop must describe the term, violation and harm in detail.", "key_value": null, "coverage_conditions": "Tenants in Berkeley units fully or partially covered by the Rent Ordinance; material lease terms mean mutually agreed terms.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": "Lease breaches that cause the landlord no actual harm cannot support an eviction.", "penalty": null, "effective_date": null, "citation": "Berkeley Rent Ordinance, Measure BB: just cause, lease breach", "quoted_span": "The alleged violation must cause substantial, actual damage to the landlord. The landlord must demonstrate that the tenant’s behavior was unreasonable. The landlord’s notice to the tenant to stop the violation (which is required before the landlord can serve an eviction notice) must specify the lease term, and describe the violation and resulting harm in enough detail for a reasonable person to understand.", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D006-01", "doc_id": "D006", "jurisdiction": "Berkeley, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "Measure BB eviction notice content and Rent Board filing", "requirement": "Termination notices must tell tenants that Rent Board advice is available with its phone and website, and the landlord must file notices and eviction lawsuits with the Rent Board within three business days of service.", "key_value": "3 business days", "coverage_conditions": "Landlords serving notices to terminate, notices to quit, or summons and complaint in Berkeley tenancies covered by the Rent Ordinance.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Berkeley Rent Ordinance, Measure BB: eviction notice and filing requirements", "quoted_span": "The landlord must file with the Rent Board a copy of any notice to terminate a tenancy, notice to quit, and summons and complaint no later than three business days after the tenant was served with the document.", "interaction": null, "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
